<!doctype html><html lang="en" class="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= h($_SESSION['csrf_token']) ?>"><title>Credential Review · ThriveWell OS</title><link rel="stylesheet" href="/build/app.css"><script defer src="/build/app.js"></script></head>
<body><main class="credential-page"><section class="credential-hero card"><span class="eyebrow">Admin verification queue</span><h1>Review credentials without making people feel interrogated.</h1><p>Use structured approvals, calm revision requests, signed access readiness, and audit logs for every sensitive action.</p><a class="link-inline" href="/dashboard">← Back to dashboard</a></section><section class="card credential-list"><div class="card-head"><h2>Review queue</h2><span><?= count($queue) ?> items</span></div><div class="state-strip" aria-live="polite"><div class="success-state" hidden>Saved.</div><div class="error-state" hidden>Check details.</div></div><?php foreach ($queue as $document): ?><article class="credential-card <?= h($document['status']) ?>"><div><strong><?= h($document['title']) ?></strong><span><?= h($document['owner_name']) ?> · <?= h($document['role_label']) ?> · <?= h($document['document_type']) ?></span><small><?= h($document['storage_disk']) ?> · <?= h($document['storage_path']) ?> · SHA-256 <?= h(substr($document['file_hash'], 0, 16)) ?></small><?php if ($document['revision_reason']): ?><p><?= h($document['revision_reason']) ?></p><?php endif; ?></div><?= status_pill($document['status']) ?><div class="review-actions"><form data-async-form action="/admin/credentials/approve" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="credential_document_id" value="<?= h((string) $document['id']) ?>"><input name="notes" placeholder="Approval note" value="Verified against private vault metadata."><button type="submit">Approve</button></form><form data-async-form action="/admin/credentials/revision" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="credential_document_id" value="<?= h((string) $document['id']) ?>"><input name="notes" placeholder="Calm revision request"><button type="submit">Request revision</button></form><form data-async-form action="/credentials/signed-download" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="credential_document_id" value="<?= h((string) $document['id']) ?>"><button type="submit">Signed access</button></form></div></article><?php endforeach; ?><?php if (!$queue) empty_state('No credentials need review', 'The queue is calm right now.'); ?></section></main></body></html>
